// Select invoice attachments and hand each one to LP-MCP as base64 JSON.
//
// Thin transport, no logic (handoff 2026-10-12 §7.1): one item per attachment
// of a kind the ledger reads (pdf / png / jpg / jpeg / tif / tiff / heic / csv
// / xlsx). LP-MCP dedupes on the file's sha256, so a re-poll of the same
// message is a harmless duplicate.
//
// 2026-10-13: the first real forward carried the invoice PDF plus the sender's
// signature art and the Outlook/QuickBooks logo as inline images. Each one was
// sent as an "invoice" and failed on the server. Now:
//   - an INLINE part is not sent: Content-Disposition inline, a Content-ID /
//     cid, or mailparser's `related` flag on the trigger's parsed attachment;
//   - an image under MIN_IMAGE_BYTES is not sent (a phone photo or a scan of an
//     invoice is far larger; PDFs, CSV and XLSX are never size-filtered);
//   - the same file name + size is sent ONCE per email (a forward often carries
//     the original's logo twice);
//   - the body text is sent when the email has NO document attachment
//     (pdf / csv / xlsx) left, so a payment reminder whose amount is in the body
//     still reaches the ledger. LP-MCP triages what arrives once more by its
//     text, so a logo that slips through here is still never an invoice.
//
// The Gmail trigger is scoped by `to:` so it never sees LP report mail or
// anything else on the shared mailbox. Do not remove that scoping.
const KEEP = /\.(pdf|png|jpe?g|tiff?|heic|csv|xlsx)$/i;
const DOC = /\.(pdf|csv|xlsx)$/i;
const IMG = /\.(png|jpe?g|tiff?|heic)$/i;
const MIN_IMAGE_BYTES = 50 * 1024;
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const headers = j.headers || {};
  const from = j.from?.value?.[0]?.address || j.from?.text || headers.from || j.From || '';
  const subject = j.subject || headers.subject || j.Subject || '';
  const received_at = j.date || headers.date || j.internalDate || null;
  const gmail_message_id = j.id || j.messageId || headers['message-id'] || null;
  const body_text = j.text || j.textPlain || (typeof j.html === 'string' ? j.html.replace(/<[^>]+>/g, ' ') : '') || '';
  // The trigger's parsed attachment list (mailparser shape) tells inline from attached.
  const parsed = Array.isArray(j.attachments) ? j.attachments : [];
  const byName = new Map();
  for (const a of parsed) {
    const n = String(a?.filename || a?.fileName || '').toLowerCase();
    if (n && !byName.has(n)) byName.set(n, a);
  }
  const isInline = (a) => !!a && (String(a.contentDisposition || '').toLowerCase() === 'inline' || !!a.contentId || !!a.cid || a.related === true);
  const bin = items[i].binary ?? {};
  const seen = new Set();
  const skipped = { inline: 0, small: 0, duplicate: 0, other: 0 };
  const picked = [];
  for (const key of Object.keys(bin)) {
    const b = bin[key] || {};
    const fileName = b.fileName ?? '';
    if (!KEEP.test(fileName)) { skipped.other++; continue; }
    if (isInline(byName.get(fileName.toLowerCase()))) { skipped.inline++; continue; }
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    if (IMG.test(fileName) && buf.length < MIN_IMAGE_BYTES) { skipped.small++; continue; }
    const sig = `${fileName.toLowerCase()}|${buf.length}`;
    if (seen.has(sig)) { skipped.duplicate++; continue; }
    seen.add(sig);
    picked.push({ fileName, mime: b.mimeType || null, buf });
  }
  const base = {
    gmail_message_id, from, subject, received_at,
    attachment_count: Object.keys(bin).length, sent_count: picked.length,
    skipped_inline: skipped.inline, skipped_small: skipped.small, skipped_duplicate: skipped.duplicate, skipped_other: skipped.other,
  };
  for (const p of picked) {
    out.push({ json: { ...base, file_name: p.fileName, mime_type: p.mime, file_b64: p.buf.toString('base64') } });
  }
  const hasDoc = picked.some((p) => DOC.test(p.fileName));
  if (!hasDoc && String(body_text).trim()) {
    out.push({ json: { ...base, file_name: null, mime_type: 'text/plain', file_b64: null, body_text: String(body_text).slice(0, 200000) } });
  }
}
return out;
